void source_run_process_heap_runtime(M &m,std::uint32_t entry,
    SourcePhysicsContactRuntimeAbi &abi,SourcePhysicsContactImage image,FP fp,
    const SourcePhysicsContactRuntimeServices &services,const O &observe) {
    if(image!=SourcePhysicsContactImage::MapPack11&&image!=SourcePhysicsContactImage::TitleUpdate15)
        throw std::runtime_error("Unverified physics contact executable image");
    FpScope scope(fp);WorldState s{m,observe,services,image};s.load(abi);
    try {
        switch(entry) {
case 0x2d7f8eu:run_2d7f8e(s);break;
case 0x2d96e3u:run_2d96e3(s);break;
case 0x2d9803u:run_2d9803(s);break;
case 0x2d9824u:run_2d9824(s);break;
case 0x2d9d19u:run_2d9d19(s);break;
case 0x2da2ebu:run_2da2eb(s);break;
case 0x2da83au:run_2da83a(s);break;
case 0x2dc5d2u:run_2dc5d2(s);break;
case 0x2dc5ffu:run_2dc5ff(s);break;
case 0x326b74u:run_326b74(s);break;
case 0x326bafu:run_326baf(s);break;
case 0x326e20u:run_326e20(s);break;

        default:throw std::runtime_error("Required original contact entry unavailable");
        }
    } catch(...) {abi=s.save();throw;}
    abi=s.save();
}
